import{_ as o,l,o as e,c as i,v as s,p as n,x as t,d,i as m,S as c}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"WebAssembly 作目标","description":"","frontmatter":{"title":"WebAssembly 作目标","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wasm-target.md","filePath":"cs/wasm-target.md","lastUpdated":1789023840000}'),p={name:"cs/wasm-target.md"};function h(A,a,b,_,u,f){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=s('<h1 id="webassembly-作目标" tabindex="-1">WebAssembly 作目标 <a class="header-anchor" href="#webassembly-作目标" aria-label="Permalink to &quot;WebAssembly 作目标&quot;">​</a></h1><div class="epigraph"><p>Wasm 是带验证的栈式虚拟 ISA：线性内存、结构化控制流、可移植。编译器可把它当后端，而不是只当浏览器插件。</p><footer>—— 据 Haas et al., Bringing the Web up to Speed with WebAssembly；Wasm 规范；对照[字节码](/cs/bytecode-interpreter) 与 ELF 整理</footer></div><p>上一课<a href="/cs/language-memory-model">内存模型</a> 是共享内存线程。Wasm 默认线性内存+可选线程扩展。缺口是<strong>当编译目标</strong>：lowering、wasm-ld、与 JS 宿主。MLIR 下一课。不重写 Transformer，不写前端框架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ELF 绑 OS ABI。Wasm：验证保证类型化栈、无跳进指令中间。控制流用 block/loop/br，利于验证，指令选择要改写任意 CFG（或用 <code>relooper</code>/异常扩展）。缺口是<strong>这一 ABI</strong>，不是 JMM 全文。</p><p>线性内存：一块数组，指针是索引。GC 提案与 reference types 在演进，点名。</p><h3 id="wasm-不是-java-字节码" tabindex="-1">Wasm 不是 Java 字节码 <a class="header-anchor" href="#wasm-不是-java-字节码" aria-label="Permalink to &quot;Wasm 不是 Java 字节码&quot;">​</a></h3><p>无内置对象模型、无内置 GC（直到提案）。更接近便携机器码。不要当 JVM 替代品讲类库。</p><p><span class="marginnote">Haas et al. 2017。Wasm Core Spec。LLVM wasm 后端。本课目标描述视角。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LLVM：<code>--target=wasm32-unknown-unknown</code> 或 <code>wasi</code>。lowering：i32/i64、内存 intrinsic、调用 <code>call_indirect</code> 表。链接：<code>wasm-ld</code> 合成模块。WASI：系统调用像精简 OS。</p>',11)),(e(),n(c,null,{default:t(()=>[m(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22LLVM%20IR%22%5D%20--%3E%20WASM%5B%22Wasm%20%E6%A8%A1%E5%9D%97%22%5D%0A%20%20WASM%20--%3E%20VAL%5B%22%E9%AA%8C%E8%AF%81%22%5D%0A%20%20VAL%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%20JIT%20%2F%20%E8%A7%A3%E9%87%8A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>与<a href="/cs/cross-compile-triple">交叉三元组</a>：<code>wasm32-wasi</code> 是三元组。与栈式 VM 课对照编码。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引擎（V8、Wasmtime）再 JIT 到 native。陷阱：越界内存。线程：共享内存+原子，模型接近 C++。不要假设可随意 <code>mmap</code> 可执行——沙箱。</p><p>异常与 DWARF：工具链可嵌调试信息；展开另套。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 MLIR。后课默认：可移植沙箱目标是 Wasm。下一课 MLIR 多层 IR。</p><p>也不把 Wasm 当汇编挖矿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Wasm：可验证的便携 ISA，作后端目标。</li><li>线性内存+结构化控制；宿主提供 WASI 或 JS。</li><li>引擎再 JIT；与 ELF 加载路径不同。</li><li>出处：Haas et al.；Wasm 规范；对照 LLVM 后端。</li></ul>',9))])}const S=o(p,[["render",h]]);export{w as __pageData,S as default};
